:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  background: #142b2b;
  color: #f5f0dc;
}

* { box-sizing: border-box; }

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background-color: #142b2b;
  background-image: linear-gradient(rgba(245, 240, 220, .035) 1px, transparent 1px), linear-gradient(90deg, rgba(245, 240, 220, .035) 1px, transparent 1px);
  background-size: 24px 24px;
}

.lock-card {
  width: min(100%, 440px);
  padding: 32px;
  border: 4px solid #f2b84b;
  border-radius: 10px;
  background: #203d3a;
  box-shadow: 10px 10px 0 #0b1c1d;
  text-align: center;
}

.card-header { margin-bottom: 28px; }
.pixel-mark { color: #f2b84b; font-size: 34px; line-height: 1; }
.eyebrow { margin: 12px 0 4px; color: #f2b84b; font-size: .8rem; font-weight: 800; letter-spacing: .18em; }
h1 { margin: 0; font-size: clamp(2rem, 9vw, 2.7rem); letter-spacing: .02em; }
.subtitle { margin: 8px 0 0; color: #c7d4c6; }

.lock-panel {
  padding: 22px 18px 18px;
  border: 2px solid #49645b;
  border-radius: 8px;
  background: #172e2e;
}

.dials { display: flex; justify-content: center; gap: clamp(10px, 5vw, 22px); margin-bottom: 22px; }
.dial { display: grid; justify-items: center; gap: 8px; }
.dial-button {
  width: 64px;
  min-height: 42px;
  border: 2px solid #668177;
  border-radius: 6px;
  background: #294743;
  color: #f5f0dc;
  font: inherit;
  font-weight: 800;
  cursor: pointer;
  transition: background-color .12s, transform .12s, border-color .12s;
}
.dial-button:hover { border-color: #f2b84b; background: #365951; }
.dial-button:active { transform: translateY(2px); background: #142b2b; }
.digit {
  display: grid;
  width: 64px;
  height: 76px;
  place-items: center;
  border: 3px solid #f2b84b;
  border-radius: 6px;
  background: #f5f0dc;
  color: #142b2b;
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 2.8rem;
  font-weight: 900;
  box-shadow: inset 0 0 0 4px #e4d7ae;
}

.open-button {
  width: 100%;
  min-height: 52px;
  border: 0;
  border-radius: 6px;
  background: #f2b84b;
  color: #142b2b;
  font: inherit;
  font-weight: 900;
  letter-spacing: .08em;
  cursor: pointer;
  transition: background-color .12s, transform .12s;
}
.open-button:hover { background: #ffd16d; }
.open-button:active { transform: translateY(2px); background: #dfa33b; }
button:focus-visible { outline: 3px solid #f5f0dc; outline-offset: 3px; }
.status { min-height: 1.5em; margin: 15px 0 0; color: #c7d4c6; }
.status.success { color: #f2b84b; font-weight: 800; }
.card-footer { display: flex; justify-content: space-between; align-items: center; margin-top: 24px; padding-top: 18px; border-top: 2px dashed #49645b; color: #c7d4c6; font-size: .85rem; font-weight: 800; letter-spacing: .1em; }
.card-footer strong { min-width: 42px; padding: 5px 10px; border-radius: 5px; background: #142b2b; color: #f2b84b; font-size: 1.15rem; letter-spacing: 0; }

@media (max-width: 400px) {
  .lock-card { padding: 24px 18px; }
  .lock-panel { padding-inline: 12px; }
}

const values = [0, 0, 0];
const dials = [...document.querySelectorAll('.dial')];
const status = document.querySelector('#status');
const attemptCount = document.querySelector('#attempt-count');
let failedAttempts = 0;
let unlocked = false;

dials.forEach((dial, index) => {
  const output = dial.querySelector('.digit');
  dial.querySelectorAll('.dial-button').forEach((button) => {
    button.addEventListener('click', () => {
      if (unlocked) return;
      values[index] = (values[index] + Number(button.dataset.step) + 10) % 10;
      output.textContent = values[index];
    });
  });
});

document.querySelector('#open-button').addEventListener('click', () => {
  if (unlocked) return;
  if (values.join('') === '372') {
    unlocked = true;
    status.textContent = 'Vault open! Nice work.';
    status.classList.add('success');
    document.querySelectorAll('.dial-button').forEach((button) => { button.disabled = true; });
    document.querySelector('#open-button').textContent = 'VAULT OPEN';
    document.querySelector('#open-button').disabled = true;
    return;
  }
  failedAttempts += 1;
  attemptCount.textContent = failedAttempts;
  status.textContent = 'Combination incorrect. Try again.';
  status.classList.remove('success');
});
